css:
/* Полосы «было → стало». Длина полосы — статичная ширина из чисел строки (без JS всё видно итогом),
   анимируется только transform: scaleX и opacity. Колонки подписи и числа фиксированной ширины: счёт не двигает полосы. */
.rb { padding-block: 64px; }
.rb__title { margin: 0 0 32px; font-size: clamp(28px, 3.4vw, 44px); line-height: 1.15; }
.rb__list { display: grid; gap: 28px; margin: 0; padding: 0; list-style: none; max-width: 760px; }
.rb__name { margin: 0 0 10px; font-size: 18px; line-height: 1.3; }
.rb__line {
  display: grid;
  grid-template-columns: var(--rb-label-w, 4.2em) minmax(0, 1fr) var(--rb-val-w, 6.2em);
  align-items: center;
  gap: 12px;
  margin: 6px 0 0;
  font-size: 15px;
}
.rb__label { color: var(--text-muted, #555b66); }
.rb__bar {
  justify-self: start;
  height: 12px;
  border-radius: 2px;                          /* радиус не больше 3px: при масштабе концы полосы тянутся */
  transform-origin: 0 50%;
}
.rb__line--was .rb__bar { width: calc(100% * var(--rb-was) / var(--rb-max)); background: var(--rb-was-color, color-mix(in srgb, var(--text-muted, #555b66) 45%, var(--background, #ffffff))); }
.rb__line--now .rb__bar { width: calc(100% * var(--rb-now) / var(--rb-max)); background: var(--rb-now-color, var(--primary, #2446d8)); } /* от 3:1 к фону */
.rb__val {
  display: inline-grid;                        /* итог и бегущее число в одной ячейке — ширина не прыгает */
  justify-items: end;
  font-size: 20px; font-weight: 600;
  font-variant-numeric: tabular-nums lining-nums;
  white-space: nowrap;
}
.rb__val > span { grid-area: 1 / 1; }
.rb__val[data-counting] .rb__final { opacity: 0; }
.rb__note { margin: 24px 0 0; font-size: 14px; color: var(--text-muted, #555b66); }
@media (max-width: 480px) {
  .rb__line { --rb-label-w: 3.6em; --rb-val-w: 5.4em; gap: 8px; }
  .rb__val { font-size: 17px; }
}
/* Ждёт появления в кадре (состояние ставит JS только ниже первого экрана). «Стало» стоит на длине «было» и невидима */
[data-rb="wait"] .rb__line--was .rb__bar { transform: scaleX(0); }
[data-rb="wait"] .rb__line--now .rb__bar { transform: scaleX(calc(var(--rb-was) / var(--rb-now))); opacity: 0; }
/* Строка k стартует в --rb-t: «было» растёт 320ms; «стало» проявляется с 200ms и за 560ms приходит к своей длине, число считается синхронно */
[data-rb="run"] .rb__line--was .rb__bar {
  transition: transform 320ms cubic-bezier(.33, 1, .68, 1) var(--rb-t, 0ms);
}
[data-rb="run"] .rb__line--now .rb__bar {
  transition: opacity 120ms linear calc(var(--rb-t, 0ms) + 200ms), transform 560ms cubic-bezier(.33, 1, .68, 1) calc(var(--rb-t, 0ms) + 240ms);
}
/* Уровень 1 (убрать): полосы и числа сразу итогом */
@media (prefers-reduced-motion: reduce) {
  [data-rb] .rb__bar { transform: none !important; opacity: 1 !important; transition: none !important; }
  .rb__val[data-counting] .rb__final { opacity: 1; }
  .rb__live { display: none; }
}
@media print {
  [data-rb] .rb__bar { transform: none !important; opacity: 1 !important; }
  .rb__val[data-counting] .rb__final { opacity: 1; }
  .rb__live { display: none; }
}

