// Полосы «было → стало»: без зависимостей. Строки по очереди, счёт «стало» синхронен со своей полосой.
(() => {
  const lists = document.querySelectorAll('[data-rb]');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  if (!lists.length || reduce.matches || !('IntersectionObserver' in window)) return; // итог сразу
  const STEP = 560, LEAD = 240, DUR = 560; // очередь строк; старт счёта от начала строки; длительность счёта (как в CSS)
  const ease = (t) => 1 - Math.pow(1 - t, 3); // = cubic-bezier(.33,1,.68,1)
  const fmts = {}, text = (el, v) => { // форматер на число знаков создаётся один раз, не на каждом кадре
    const d = +el.dataset.rbDecimals || 0;
    return (fmts[d] || (fmts[d] = new Intl.NumberFormat('ru-RU', { minimumFractionDigits: d, maximumFractionDigits: d }))).format(v) + (el.dataset.rbSuffix || '');
  };
  const count = (el, delay) => {
    const live = el.querySelector('.rb__live'), from = +el.dataset.rbFrom, to = +el.dataset.rbTo, t0 = performance.now() + delay;
    const tick = (now) => {
      if (reduce.matches) { el.removeAttribute('data-counting'); return; } // настройку включили на лету — сразу итог
      const p = Math.min(Math.max((now - t0) / DUR, 0), 1);
      live.textContent = text(el, from + (to - from) * ease(p));
      if (p < 1) requestAnimationFrame(tick); else { el.removeAttribute('data-counting'); live.textContent = ''; }
    };
    requestAnimationFrame(tick);
  };
  const io = new IntersectionObserver((es) => es.forEach((e) => {
    if (!e.isIntersecting) return;
    io.unobserve(e.target); e.target.dataset.rb = 'run'; // один раз, без повтора при прокрутке назад
    e.target.querySelectorAll('.rb__row').forEach((row, k) => {
      row.style.setProperty('--rb-t', k * STEP + 'ms');
      row.querySelectorAll('[data-rb-to]').forEach((v) => count(v, k * STEP + LEAD));
    });
  }), { threshold: 0.4 });
  lists.forEach((list) => {
    const r = list.getBoundingClientRect();
    if (r.top < innerHeight && r.bottom > 0) return; // в кадре при загрузке — итог без анимации
    list.querySelectorAll('[data-rb-to]').forEach((v) => { // до старта «стало» показывает число «было»
      if (!v.querySelector('.rb__live') || !isFinite(+v.dataset.rbFrom) || !isFinite(+v.dataset.rbTo)) { v.removeAttribute('data-rb-to'); return; }
      v.setAttribute('data-counting', ''); v.querySelector('.rb__live').textContent = text(v, +v.dataset.rbFrom);
    });
    list.dataset.rb = 'wait'; io.observe(list);
  });
})();

gsap_alt:
// Только если GSAP уже есть в проекте: npm i gsap (Standard License, не MIT), без CDN. Разметка и CSS те же, JS рецепта не подключать.
// Та же хореография: строка k стартует в k × 0,56 с, «было» 0,32 с, «стало» с длины «было» за 0,56 с вместе со счётом.
// Не для первого экрана: fromTo сразу прячет полосы до прокрутки.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  if (conditions.reduce) return; // итог сразу — это делает CSS
  gsap.utils.toArray('[data-rb]').forEach((list) => {
    const tl = gsap.timeline({ paused: true });
    gsap.utils.toArray('.rb__row', list).forEach((row, k) => {
      const [was, now] = row.querySelectorAll('.rb__bar'), v = row.querySelector('[data-rb-to]'), live = v.querySelector('.rb__live');
      const cs = getComputedStyle(row), d = +v.dataset.rbDecimals || 0, at = k * 0.56;
      const f = new Intl.NumberFormat('ru-RU', { minimumFractionDigits: d, maximumFractionDigits: d });
      const show = (x) => { live.textContent = f.format(x) + (v.dataset.rbSuffix || ''); };
      const n = { x: +v.dataset.rbFrom };
      v.setAttribute('data-counting', ''); show(n.x); // до старта «стало» показывает число «было»
      tl.fromTo(was, { scaleX: 0 }, { scaleX: 1, duration: 0.32, ease: 'power2.out' }, at) // power2.out = cubic-bezier(.33,1,.68,1)
        .fromTo(now, { opacity: 0 }, { opacity: 1, duration: 0.12, ease: 'none' }, at + 0.2)
        .fromTo(now, { scaleX: parseFloat(cs.getPropertyValue('--rb-was')) / parseFloat(cs.getPropertyValue('--rb-now')) }, { scaleX: 1, duration: 0.56, ease: 'power2.out' }, at + 0.24)
        .to(n, { x: +v.dataset.rbTo, duration: 0.56, ease: 'power2.out', onUpdate: () => show(n.x),
          onComplete: () => { v.removeAttribute('data-counting'); live.textContent = ''; } }, at + 0.24);
    });
    ScrollTrigger.create({ trigger: list, start: 'top 70%', once: true, onEnter: () => tl.play() });
  });
  // настройку включили на лету: matchMedia откатит полосы, а числа покажем итогом
  return () => document.querySelectorAll('[data-rb] [data-counting]').forEach((v) => v.removeAttribute('data-counting'));
});
